import{_ as o,l as i,o as e,c as t,v as r,p as c,x as d,d as l,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"预读","description":"","frontmatter":{"title":"预读","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/readahead.md","filePath":"cs/readahead.md","lastUpdated":1789023840000}'),h={name:"cs/readahead.md"};function E(A,a,m,_,u,f){const s=i("Mermaid");return e(),t("div",null,[a[1]||(a[1]=r('<h1 id="预读" tabindex="-1">预读 <a class="header-anchor" href="#预读" aria-label="Permalink to &quot;预读&quot;">​</a></h1><div class="epigraph"><p>顺序读一旦被认出，内核就在当前请求之后再拉若干页进页缓存，用带宽换掉下一次缺页。</p><footer>—— 据 Paixao 等对 Linux readahead 的实现讨论；Arpaci-Dusseau, <em>OSTEP</em> 对预取的整理；McKusick 对簇读的背景</footer></div><p><a href="/cs/device-nodes">上一课</a>已能打开块设备或文件。每次 <code>read</code> 若只填一页，HDD 与即便是 NVMe 也会把延迟付 N 次。<a href="/cs/page-cache">页缓存</a> 的 miss 路径可以<strong>多填</strong>。缺口是预读窗口：何时放大、何时停、<code>fadvise</code> 如何提示。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>随机读预取会害：把有用页挤出，还占用设备队列。内核跟踪某文件描述的顺序程度，命中则把 readahead 窗口加倍，直到上限；探测失败则收缩。<code>posix_fadvise(WILLNEED/SEQUENTIAL/RANDOM)</code> 改策略。缺口：mmap 顺序扫描同样走异步预读；<a href="/cs/sparse-files">稀疏</a> 洞不应把后面数据当顺序；<code>O_DIRECT</code> 绕过页缓存则本课对象不在。</p><p><span class="marginnote">窗口以页计，背后可能合并成一次大 I/O。预读是启发式，不是 POSIX 保证。本课不把 madvise 的全部体系写成虚存百科。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>read</code> miss：提交当前页 I/O，同时对后续偏移 <code>readpages</code>。完成的页插入树，标 readahead 以便统计命中。写不预读。对照磁盘调度：预读制造顺序大请求，<a href="/cs/blk-schedulers">块层</a> 更易合并——那是下一课序。对照 NFS：预读变成超前 READ RPC，语义仍受缓存约束。</p>',8)),(e(),c(p,null,{default:d(()=>[n(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEQ%5B%22%E8%AE%A4%E5%87%BA%E9%A1%BA%E5%BA%8F%E8%AF%BB%22%5D%20--%3E%20WIN%5B%22%E6%94%BE%E5%A4%A7%E7%AA%97%E5%8F%A3%22%5D%0A%20%20WIN%20--%3E%20IO%5B%22%E5%BC%82%E6%AD%A5%E5%A1%AB%E5%90%8E%E7%BB%AD%E9%A1%B5%22%5D%0A%20%20IO%20--%3E%20CACHE%5B%22%E9%A1%B5%E7%BC%93%E5%AD%98%22%5D%0A%20%20RAND%5B%22%E9%9A%8F%E6%9C%BA%E6%A8%A1%E5%BC%8F%22%5D%20--%3E%20OFF%5B%22%E5%85%B3%E9%97%AD%E6%88%96%E6%94%B6%E7%BC%A9%22%5D%0A"})]),fallback:d(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>预读把「文件是流」的统计结构变成 I/O 形状：顺序工作负载接近设备带宽，随机工作负载不应被好心伤害。它不改变崩溃一致性，只改变热页集合。不要把预读写成 CPU 硬件预取器的同构课：缺的是毫秒级存储，不是纳秒级 cache line。</p><p>与 <a href="/cs/fs-mmap-coherence">mmap 一致</a>：fault 路径同样可以触发文件预读，共享同一窗口记账。</p><p>实现上：异步预读完成时若用户已改成随机模式，多读的页仍插入 Cache，可能挤热点。mmap 顺序故障用同一套窗口，但 vma 跨越文件空洞要停。 读法上只引用<a href="/cs/device-nodes">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 接口进阶」课序里，对象是 <strong>预读</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入块层 <code>iostat</code> 的全部指标。不保证跨文件的全局预读调度。下一课故意关掉这层缓存：<code>O_DIRECT</code>。</p><p>版本字段会变，课序钉的是机制对象「预读」，不是某一主线内核的结构体名。 后课默认：顺序读可被启发式预取。绕过页缓存的对齐 I/O，下一课 O_DIRECT。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>预读按顺序度放大窗口，把后续页填进页缓存。</li><li>提示与随机模式可关掉它。</li><li>直接 I/O 是下一课。</li><li>出处：Linux readahead；<em>OSTEP</em>；McKusick 簇读。</li></ul>',11))])}const T=o(h,[["render",E]]);export{D as __pageData,T as default};
